for i in range(14):
    for j in range(i+1,14):
        s.add(Implies(e[(i,j)], color[i] != color[j]))
def add_no_cycle(k):
    count = 0
    for comb in itertools.combinations(range(14), k):
        verts = list(comb)
        for perm_tup in itertools.permutations(verts[1:]):
            p = (verts[0],) + perm_tup
            if p[1] > p[-1]: continue
            cycle_ors = []
            for ii in range(k):
                u = p[ii]
                v = p[(ii+1) % k]
                edge_var = e[(min(u,v), max(u,v))]
                cycle_ors.append(Not(edge_var))
            s.add(Or(cycle_ors))
            count += 1
    print(f"Added {count} constraints for no C{k}")
for kk in [3,4,5,6]:
    add_no_cycle(kk)
num_edges = Sum([If(e[key], 1, 0) for key in e])
s.add(num_edges >= 18)
print(s.check())
if s.check() == sat:
    m = s.model()
    edges = []
    for key in e:
        if is_true(m[e[key]]):
            edges.append(key)
    print(len(edges))
